/* @lc app=leetcode id=4002 lang=kotlin */ class Solution { fun inv(x: Long): Long = java.math.BigInteger.valueOf(x).modPow(java.math.BigInteger.valueOf(1_000_000_005L), java.math.BigInteger.valueOf(1_000_000_007L)).toLong() fun c(f: List<Long>, a: Int, b: Int): Long = if (b < 0 || b > a) 0L else f[a] * inv(f[b]) % 1_000_000_007L * inv(f[a - b]) % 1_000_000_007L fun countValidSequences(n: Int, k: Int): Int = (1..n).runningFold(1L) { a, i -> a * i % 1_000_000_007L }.let { f -> ((c(f, n - 1, k - 1) - (if ((n - k) % 2 == 0) c(f, (n - k) / 2 + k - 1, k - 1) else 0L) + 1_000_000_007L) % 1_000_000_007L).toInt() } }